class AppShell extends StatefulWidget { const AppShell({super.key}); @override State<AppShell> createState()=>_AppShellState(); }
class _AppShellState extends State<AppShell> {
  final store=Store(); int tab=0; bool loading=true;
  @override void initState(){super.initState();store.load().then((_){if(mounted)setState(()=>loading=false);});}
  Future<bool> gate() async { if(store.registered)return true; await Navigator.push(context,MaterialPageRoute(builder:(_)=>ShopFormPage(store:store))); return store.registered; }
  @override Widget build(BuildContext context){
    if(loading)return const Scaffold(body:Center(child:CircularProgressIndicator(color:primary)));
    final pages=[HomePage(store:store,gate:gate),ItemsPage(store:store,gate:gate),CustomersPage(store:store,gate:gate),IssuedPage(store:store,gate:gate),SettingsPage(store:store)];
    return AnimatedBuilder(animation:store,builder:(_,__)=>Scaffold(body:pages[tab],bottomNavigationBar:NavigationBar(height:78,backgroundColor:const Color(0xFFEAF2EF),indicatorColor:const Color(0xFFCDEEE4),selectedIndex:tab,onDestinationSelected:(i)=>setState(()=>tab=i),destinations:const[
      NavigationDestination(icon:Icon(Icons.grid_view_outlined),selectedIcon:Icon(Icons.grid_view_rounded),label:'Home'),
      NavigationDestination(icon:Icon(Icons.inventory_2_outlined),selectedIcon:Icon(Icons.inventory_2_rounded),label:'Items'),
      NavigationDestination(icon:Icon(Icons.people_outline),selectedIcon:Icon(Icons.people_rounded),label:'Customers'),
      NavigationDestination(icon:Icon(Icons.assignment_outlined),selectedIcon:Icon(Icons.assignment_rounded),label:'Issued'),
      NavigationDestination(icon:Icon(Icons.settings_outlined),selectedIcon:Icon(Icons.settings_rounded),label:'Settings'),
    ])));
  }
}

