Future<void> confirmDelete(BuildContext context,Future<void> Function() action) async {final ok=await showDialog<bool>(context:context,builder:(_)=>AlertDialog(title:const Text('Delete?'),content:const Text('This action cannot be undone.'),actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('Delete'))]))??false;if(ok)await action();}
Future<void> checkUpdate(BuildContext context) async {showDialog(context:context,barrierDismissible:false,builder:(_)=>const Center(child:CircularProgressIndicator(color:primary)));try{final r=await http.get(Uri.parse('https://api.github.com/repos/shanpalia/RentFlow/releases/latest'),headers:{'Accept':'application/vnd.github+json'});if(context.mounted)Navigator.pop(context);if(!context.mounted)return;if(r.statusCode==200){final j=jsonDecode(r.body) as Map<String,dynamic>;final tag='${j['tag_name']??''}';showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('Update Check'),content:Text(tag.isEmpty?'You are using the latest available version.':'Latest RentFlow release: $tag'),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('OK'))]));}else{ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Could not check for updates right now.')));}}catch(_){if(context.mounted)Navigator.pop(context);if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Update check failed. Please try again.')));}}
